    private String language(String tag){if(tag==null||!tag.matches("[A-Za-z]{2,3}([-_][A-Za-z0-9]{2,8})*")||tag.equals("und"))return "Idioma não informado";Locale l=Locale.forLanguageTag(tag.replace('_','-'));String name=l.getDisplayName(new Locale("pt","BR"));return name.isEmpty()?"Idioma não informado":name;}
    private void setAspect(int mode){aspect=mode;Legacy.call(video,"setResizeMode",mode);profiles.preference("aspect",mode);notice(mode==0?"Ajustar à tela":mode==4?"Preencher sem distorcer":"Esticar à tela");}
    private void fit(){List<Panel.Choice> rows=new ArrayList<>();rows.add(new Panel.Choice("Ajustar à tela","Preserva a imagem inteira e a proporção original","fit",aspect==0,()->setAspect(0)));rows.add(new Panel.Choice("Preencher","Preenche a tela com corte nas bordas","fit",aspect==4,()->setAspect(4)));rows.add(new Panel.Choice("Esticar","Ocupa a tela alterando a proporção","fit",aspect==3,()->setAspect(3)));open("Ajuste de imagem","Use também dois dedos sobre o vídeo para ajustar o enquadramento.",rows);}
    private void chooseEpisode(){if(!metadata.series())return;Panel p=open("Episódios",metadata.title,Collections.emptyList());androidx.recyclerview.widget.RecyclerView cards=new androidx.recyclerview.widget.RecyclerView(activity);cards.setLayoutManager(new androidx.recyclerview.widget.LinearLayoutManager(activity));cards.setItemAnimator(null);cards.setAdapter(new EpisodeCards(activity,metadata,episode(),index->{p.dismiss();save();pendingSeek=-1;Legacy.call(activity,"q1",Integer.valueOf(index));show(true);}));p.content(cards);
        if(!metadata.seasons.isEmpty()){HorizontalScrollView scroll=new HorizontalScrollView(activity);scroll.setHorizontalScrollBarEnabled(false);LinearLayout seasons=Ui.row(activity);for(Movie.Season season:metadata.seasons){TextView chip=Ui.button(activity,season.name.isEmpty()?"Temporada":season.name,season.id==metadata.id,()->{if(season.id!=metadata.id){save();Movie m=new Movie();m.id=season.id;m.kind=metadata.kind;Routes.play(activity,m);activity.finish();}});LinearLayout.LayoutParams lp=Ui.lp(-2,dp(48));lp.setMargins(0,0,dp(8),dp(12));seasons.addView(chip,lp);}scroll.addView(seasons);p.header(scroll);}}
    private SourceDiscovery.Target confirmedSource(){org.json.JSONObject bindings=profiles.active().preferences.optJSONObject("source_identities");if(bindings!=null)try{org.json.JSONObject saved=bindings.optJSONObject(sourceKey());if(saved!=null)return SourceDiscovery.Target.parse(saved);}catch(Exception ignored){}return null;}
    private void refreshEpisodeMetadata(){Movie current=metadata;if(!current.series())return;SourceDiscovery.Target confirmed=confirmedSource();Catalog.async(()->{Movie copy=Movie.parse(current.json());copy.episodeDetails.addAll(current.episodeDetails);com.mgs.carparking.modern.sources.ContentMetadata.enrich(activity,copy,confirmed);return copy;},new Catalog.Callback<Movie>(){public void ready(Movie m){if(!closed&&metadata==current)metadata=m;}public void failed(String e){}});}
    private void catalogOnce(){catalogOnce(Boolean.TRUE.equals(Legacy.call(exo(),"getPlayWhenReady")));}
    private void catalogOnce(boolean playing){if(CATALOG_ONCE.size()>32)CATALOG_ONCE.clear();CATALOG_ONCE.put(profile+":"+sourceKey(),new Resume(playing));}
    private Boolean consumeCatalogResume(){Resume value=CATALOG_ONCE.remove(profile+":"+sourceKey());return value!=null&&SystemClock.elapsedRealtime()-value.at<60000?value.playing:null;}
    private void automatic(boolean force){
        if(closed||manualSource||!profile.equals(profiles.activeId()))return;String key=sourceKey();if(autoBusy&&autoKey.equals(key))return;if(!force&&autoKey.equals(key))return;autoKey=key;autoBusy=true;int generation=++autoGeneration;Movie content=metadata;int index=episode();SourceDiscovery.Target confirmed=confirmedSource();sourceStatus.setText("Verificando fontes com áudio PT-BR…");
        Catalog.async(()->AutomaticSources.discover(activity.getApplicationContext(),content,index,confirmed,()->generation==autoGeneration),new Catalog.Callback<AutomaticSources.Result>(){
            public void ready(AutomaticSources.Result result){if(closed||generation!=autoGeneration||!key.equals(sourceKey())||!profile.equals(profiles.activeId()))return;autoBusy=false;autoResult=result;sourceStatus.setText(result.message);if(!manualSource&&foreground){boolean selected=useAutomaticCandidate();if(!selected)offerCombination(false);}}
            public void failed(String e){if(closed||generation!=autoGeneration)return;autoBusy=false;sourceStatus.setText("Não foi possível verificar novas fontes. Catálogo preservado.");}
        });
    }
    private boolean useAutomaticCandidate(){if(autoResult==null||!foreground)return false;SourceDiscovery.Session best=autoResult.best(activity,preferredQuality,rejectedSources);if(best==null)return false;if(external!=null&&best.provider.equals(external.provider))return true;
        PlaybackTracks.Track current=tracks().currentVideo();if(current==null||tracks().tracks(1).isEmpty()){awaitAutoStart=true;return false;}int offered=AutomaticSources.height(activity,best,preferredQuality);if(external==null&&current!=null&&(preferredQuality>0&&current.height>=preferredQuality||preferredQuality<=0&&current.height>=offered))return false;
        autoPlaying=verifyingAudio?autoPlaying:Boolean.TRUE.equals(Legacy.call(exo(),"getPlayWhenReady"));switchSource(best,true);if(external!=best)return false;verifyingAudio=true;Legacy.call(exo(),"setPlayWhenReady",false);sourceStatus.setText("Confirmando áudio PT-BR da fonte…");return true;
    }
    private void verifyAutomaticAudio(){if(!verifyingAudio||external==null)return;if(((Number)Legacy.call(exo(),"getPlaybackState")).intValue()!=3){if(SystemClock.elapsedRealtime()-sourceStarted>10000)recoverSource();return;}List<PlaybackTracks.Track> audio=tracks().tracks(1);for(PlaybackTracks.Track track:audio)if(AutomaticSources.brazilian(track.language)){tracks().select(track);verifyingAudio=false;Legacy.call(exo(),"setPlayWhenReady",autoPlaying);sourceStatus.setText("PT-BR · "+external.provider);return;}if(!audio.isEmpty()||SystemClock.elapsedRealtime()-sourceStarted>10000)recoverSource();}
    private void recoverSource(){if(closed||external==null)return;if(combination!=null){combination=null;cancelMerge();sourceStatus.setText("Voltando à versão dublada do catálogo…");Ui.toast(activity,"A combinação não ficou estável. Voltando à versão dublada.");catalogSource();return;}SourceDiscovery.Session failed=external;boolean intended=verifyingAudio?autoPlaying:Boolean.TRUE.equals(Legacy.call(exo(),"getPlayWhenReady"));long position=pendingSeek>=0?pendingSeek:Legacy.number(exo(),"getCurrentPosition");pendingSeek=-1;verifyingAudio=false;rejectedSources.add(failed.provider);bufferingAt=0;manualSource=false;if(autoResult!=null){boolean next=useAutomaticCandidate();if(next){autoPlaying=intended;pendingSeek=position;sourceStatus.setText("Tentando outra fonte PT-BR…");return;}external=failed;}
        Legacy.seek(exo(),Math.max(0,position));save();profiles.flush();sourceStatus.setText("Voltando à versão do catálogo…");catalogOnce(intended);if(autoResult!=null)AutomaticSources.invalidate(autoResult.target);Legacy.call(activity,"c2",Integer.valueOf(Legacy.integer(dto(),"getAudio_type")));
    }
    private void next(){if(episode()+1>=episodes().size()){Ui.toast(activity,"Você chegou ao último episódio disponível.");return;}save();manualNext=true;try{Legacy.call(activity,"loadVideoNext");}finally{manualNext=false;}show(true);}
    private static String format(long ms){long s=Math.max(0,ms/1000);return s>=3600?String.format(Locale.ROOT,"%d:%02d:%02d",s/3600,s/60%60,s%60):String.format(Locale.ROOT,"%d:%02d",s/60,s%60);}
